*{box-sizing:border-box}body{margin:0;background:#eef3f8;font-family:Arial,sans-serif;color:#142b47}.toolbar{text-align:center;padding:14px}.toolbar button{background:#0757a4;color:#fff;border:0;border-radius:7px;padding:10px 20px;font-weight:700;cursor:pointer}.sheet{width:190mm;min-height:277mm;margin:0 auto 15px;background:#fff;padding:8mm 9mm;display:grid;grid-template-rows:1fr 1fr;gap:7mm}.student-row{display:grid;grid-template-columns:85.6mm 85.6mm;gap:6mm;align-items:start;justify-content:center}.card{width:85.6mm;height:128mm;overflow:hidden;border:1px solid #cdd9e6;border-radius:5mm;background:#fff;position:relative}.top{height:23mm;padding:3mm 4mm;background:linear-gradient(120deg,#082f67,#0757a4 70%,#118de0);color:#fff;border-bottom:3mm solid #76b82a}.brand{display:flex;align-items:center;gap:3mm}.brand img{width:14mm;height:14mm;object-fit:contain;border-radius:50%;background:#fff;padding:1mm}.school{font-size:15px;font-weight:800}.sub{font-size:7px;letter-spacing:1px;margin-top:2px}.body{padding:4mm 5mm}.profile{display:flex;gap:4mm;align-items:center;margin-bottom:2mm}.photo{width:24mm;height:29mm;border:1mm solid #4e9c4b;border-radius:3mm;overflow:hidden;background:#f3f6f9}.photo img{width:100%;height:100%;object-fit:cover}.placeholder{height:100%;display:flex;align-items:center;justify-content:center;text-align:center;font-size:7px;font-weight:700}.name{font-size:14px;font-weight:800;color:#082f67;margin-bottom:2mm}.active{display:inline-block;background:#eaf7df;color:#388020;border-radius:20px;padding:1.2mm 2mm;font-size:7px;font-weight:800}.line{display:grid;grid-template-columns:30mm 1fr;padding:1.15mm 0;border-bottom:1px dashed #d7e0ea;font-size:8px}.line b{color:#617187}.lower{display:flex;justify-content:space-between;align-items:flex-start;padding:1.5mm 5mm 12mm}.qr{width:19mm;height:19mm;border:1px solid #0757a4;padding:1mm}.qr img{width:100%;height:100%}.session{text-align:center;width:38mm;font-size:7px}.year{font-size:12px;font-weight:800;